import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.DjfA6S92.js";const u=JSON.parse('{"title":"Entry","description":"","frontmatter":{},"headers":[],"relativePath":"guide/entry.md","filePath":"guide/entry.md"}'),n={name:"guide/entry.md"};function i(l,e,p,c,h,s){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="entry" tabindex="-1">Entry <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Entry&quot;">​</a></h1><p>我将<strong>最基础</strong>的前端的知识点分为三个部分：</p><ul><li>HTML CSS JavaScript（闭包、作用域、异步、继承）</li><li>网络、性能、测试、编码</li><li>自动化、工程化的开发</li></ul><p>这三个划分出来的只是最为基础的内容，学习这部分内容一方面需要对于书面知识的阅读，也需要在项目中加以实践。</p><h2 id="naive" tabindex="-1">Naive <a class="header-anchor" href="#naive" aria-label="Permalink to &quot;Naive&quot;">​</a></h2><p>基础的面试问题题库已经有很多了，个人觉得这个里面的题大概是入门级别的，刚学的时候看看就可以了。</p><blockquote><p><a href="https://github.com/qiu-deqing/FE-interview" target="_blank" rel="noreferrer">中文前端面试大全：qiu-deqing/FE-interview</a></p></blockquote><p>白皮书里关于非技术的问题值得一读。</p><blockquote><p><a href="https://github.com/yangshun/tech-interview-handbook" target="_blank" rel="noreferrer">yangshun/tech-interview-handbook</a></p></blockquote><p>这本书里面梳理的非常全面，可以作为知识体系的梳理来进行学习。</p><blockquote><p><a href="https://frontendmasters.gitbooks.io/front-end-developer-handbook-2018/" target="_blank" rel="noreferrer">front-end-developer-handbook-2018</a></p></blockquote><h2 id="interesting" tabindex="-1">Interesting <a class="header-anchor" href="#interesting" aria-label="Permalink to &quot;Interesting&quot;">​</a></h2><p>关于一些Javascript里细节的点，可以看看这位大哥的博客，写的很清晰，代码实现很完整。</p><blockquote><p><a href="https://github.com/mqyqingfeng/Blog" target="_blank" rel="noreferrer">冴羽的博客</a></p></blockquote><p>《前端要给力之系列》是一系列非常有趣的文章，同时讲的非常深入</p><blockquote><p><a href="/Interview-Book/Collection/Geili.html">前端要给力之系列</a></p></blockquote><p>如果你喜欢看一些函数式编程、编译原理之类的东西，那么可以看看何幻大神的知乎专栏进行一些<s>初步</s>深入的学习。</p><blockquote><p><a href="https://zhuanlan.zhihu.com/self-discipline" target="_blank" rel="noreferrer">业余程序员的个人修养</a></p></blockquote><h2 id="recommend" tabindex="-1">Recommend <a class="header-anchor" href="#recommend" aria-label="Permalink to &quot;Recommend&quot;">​</a></h2><p>这本书里面涵盖的知识点非常基础，作者整理了四个月，刷完了十几本书，还有leetcode四百题，梳理了非常多的知识结构。</p><p>其中包括<strong>计算机网络、操作系统、算法、面向对象、数据库、java、分布式、工具</strong>等等丰富的内容，这也是我在后文里提到的内容。</p><p>我极力推崇这样的知识梳理的repo，在这个repo中扩展了我在本文最后提到的书本中的知识点。<br> 如果你希望加强基础的学习，或者在往后端进行技术拓展，这本书可以作为大纲梳理。</p><blockquote><p><a href="https://github.com/CyC2018/Interview-Notebook" target="_blank" rel="noreferrer">面试白皮书</a></p></blockquote>',23)])])}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
